-- Krok 1 na PROD: kontrola wstępna (musi przejść bez błędu). Nic nie zapisuje.
DO $$
DECLARE missing text;
BEGIN
  SELECT string_agg(r.t || '.' || r.c, ', ') INTO missing
  FROM (VALUES ('product', 'id'), ('product', 'producer_id'), ('product', 'status'), ('product', 'name'), ('product', 'country_of_production'), ('product', 'floor_area_m2'), ('product', 'built_up_area_m2'), ('product', 'description'), ('product', 'completion_standard'), ('product', 'production_lead_time_weeks_min'), ('product', 'production_lead_time_weeks_max'), ('product', 'on_site_assembly_days_min'), ('product', 'on_site_assembly_days_max'), ('product', 'house_price_min_cents'), ('product', 'house_price_max_cents'), ('product', 'structural_warranty_years'), ('product', 'category'), ('product', 'rooms'), ('product', 'bedrooms'), ('product', 'bathrooms'), ('product', 'storeys'), ('product', 'external_dimensions'), ('product', 'roof_type'), ('product', 'construction_system'), ('product', 'foundation_options'), ('product', 'customization_scope'), ('product', 'currency'), ('product', 'price_includes'), ('product', 'price_excludes'), ('product', 'featured'), ('product', 'created_at'), ('product', 'updated_at'), ('product', 'deleted_at'), ('product', 'family'), ('product', 'spa_subcategory'), ('product', 'technical_specs'), ('product', 'cover_image_url'), ('product', 'container_subcategory'), ('product', 'installation_warranty_years'), ('product', 'service_scope_description'), ('product', 'transport_dimensions'), ('product', 'crane_requirements'), ('product', 'min_plot_width_m'), ('product', 'room_layout'), ('product', 'faq'), ('product', 'simplified_permit_eligible'), ('product', 'client_requirements'), ('product', 'video_url'), ('product', 'slug'), ('product', 'outdoor_tv_mounting'), ('product', 'outdoor_tv_sun_exposure'), ('product', 'foundation_status'), ('product_translation', 'id'), ('product_translation', 'product_id'), ('product_translation', 'locale'), ('product_translation', 'name'), ('product_translation', 'description'), ('product_translation', 'created_at'), ('product_translation', 'updated_at'), ('product_translation', 'room_layout'), ('product_translation', 'faq'), ('product_translation', 'ai_generated_name'), ('product_translation', 'ai_generated_description'), ('product_translation', 'ai_translated_from_name'), ('product_translation', 'ai_translated_from_description'), ('product_translation', 'client_requirements'), ('product_translation', 'foundation_options'), ('product_translation', 'technical_specs'), ('product_translation', 'construction_system'), ('product_translation', 'roof_type'), ('product_translation', 'customization_scope'), ('product_translation', 'service_scope_description'), ('product_country_eligibility', 'product_id'), ('product_country_eligibility', 'country_code'), ('product_country_eligibility', 'status'), ('product_country_eligibility', 'reason'), ('product_country_eligibility', 'created_at'), ('product_country_eligibility', 'updated_at'), ('product_variant', 'id'), ('product_variant', 'product_id'), ('product_variant', 'completion_standard'), ('product_variant', 'variant_label'), ('product_variant', 'price_min_cents'), ('product_variant', 'price_max_cents'), ('product_variant', 'scope_summary'), ('product_variant', 'is_default'), ('product_variant', 'sort_order'), ('product_variant', 'created_at'), ('product_variant', 'updated_at'), ('product_variant', 'deleted_at'), ('product_variant', 'price_on_request'), ('product_variant', 'excluded_scope'), ('product_variant_translation', 'id'), ('product_variant_translation', 'product_variant_id'), ('product_variant_translation', 'locale'), ('product_variant_translation', 'scope_summary'), ('product_variant_translation', 'created_at'), ('product_variant_translation', 'updated_at'), ('product_variant_translation', 'excluded_scope'), ('product_variant_translation', 'variant_label'), ('cost_line_item', 'id'), ('cost_line_item', 'product_variant_id'), ('cost_line_item', 'label'), ('cost_line_item', 'status'), ('cost_line_item', 'responsible_party'), ('cost_line_item', 'sort_order'), ('cost_line_item', 'created_at'), ('cost_line_item', 'updated_at'), ('cost_line_item_label_translation', 'id'), ('cost_line_item_label_translation', 'label_pl'), ('cost_line_item_label_translation', 'locale'), ('cost_line_item_label_translation', 'translated_label'), ('cost_line_item_label_translation', 'created_at'), ('cost_line_item_label_translation', 'updated_at'), ('product_option_group_assignment', 'id'), ('product_option_group_assignment', 'product_id'), ('product_option_group_assignment', 'group_id'), ('product_option_group_assignment', 'created_at'), ('document', 'id'), ('document', 'r2_key'), ('document', 'filename'), ('document', 'mime_type'), ('document', 'size_bytes'), ('document', 'purpose'), ('document', 'is_cover'), ('document', 'sort_order'), ('document', 'owner_user_id'), ('document', 'product_id'), ('document', 'order_stage_event_id'), ('document', 'producer_id'), ('document', 'created_at'), ('document', 'deleted_at'), ('document', 'product_variant_id'), ('document', 'project_quote_id'), ('document', 'product_option_id'), ('document', 'floor_level')) AS r(t, c)
  WHERE NOT EXISTS (
    SELECT 1 FROM information_schema.columns k
    WHERE k.table_schema = 'public' AND k.table_name = r.t AND k.column_name = r.c
  );
  IF missing IS NOT NULL THEN
    RAISE EXCEPTION 'Na tej bazie brakuje kolumn (najpierw wdróż wcześniejsze migracje): %', missing;
  END IF;
END $$;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM producer WHERE id = 'e0030000-0000-4000-8000-000000000103') THEN
    RAISE EXCEPTION 'Na tej bazie nie ma producenta Wencela (najpierw wgraj pełną paczkę _promote_wencel_to_prod), przerywam';
  END IF;
  IF (SELECT count(*) FROM product_option_group WHERE producer_id = 'e0030000-0000-4000-8000-000000000103' AND deleted_at IS NULL) < 4 THEN
    RAISE EXCEPTION 'Na tej bazie brakuje grup opcji Wencela, przerywam';
  END IF;
  IF EXISTS (SELECT 1 FROM product WHERE slug IN ('woz-24')
             AND id NOT IN ('79ac2ca8-124b-56eb-a910-39ec31597473')) THEN
    RAISE EXCEPTION 'Adres (slug) jednego z produktów jest już zajęty przez inny produkt, przerywam';
  END IF;
END $$;
